const BasePrinter = require('./printer');
const { default: chalk } = require('chalk');
const { default: prettyMs } = require('pretty-ms');
const { default: figure } = require('figures');

function getBarText(percent, maxBarSize) {
    maxBarSize = Math.max(0, maxBarSize);
    const barNumber = Math.max(Math.ceil((percent / 100) * maxBarSize), 1);
    return (
        chalk.blue(new Array(barNumber + 1).join(figure.square)) +
        chalk.blue.dim(
            new Array(Math.max(0, maxBarSize - barNumber + 1)).join(
                figure.square
            )
        )
    );
}

function padLeft(str, width) {
    return new Array(Math.max(0, width - str.length + 1)).join(' ') + str;
}

function padRight(str, width) {
    return str + new Array(Math.max(0, width - str.length + 1)).join(' ');
}

class CliPrinter extends BasePrinter {
    constructor(options = {}) {
        super(options);

        chalk.level = options.enableColor !== false ? 3 : 0;
        this.processStart = Date.now();

        this.nameMaxLen = options.nameMaxLen || 30;
    }

    groupData(data, columnIndex) {
        const grouping = {};

        data.forEach((point) => {
            const columnName = point.name.split(':')[columnIndex];
            grouping[columnName] = grouping[columnName] || [];

            grouping[columnName].push(point);
        });

        return grouping;
    }

    _print(data, dimensions, indentation = 0) {
        const [dimension] = dimensions;
        const subData = this.groupData(data, dimension);

        if (dimensions.length > 1) {
            return Object.keys(subData).forEach((groupedName) => {
                const dataPart = subData[groupedName];

                console.log(
                    new Array(indentation + 1).join('  ') +
                        chalk.underline(groupedName)
                );
                this._print(dataPart, dimensions.slice(1), indentation + 1);
            });
        }

        // Group/aggregate the data
        const points = Object.keys(subData)
            .map((groupedName) => {
                const dataPart = subData[groupedName];

                // Special case: make the labels pretty!
                if (
                    indentation === 0 &&
                    dimensions.length === 1 &&
                    dimension !== 1
                ) {
                    // Example: <pid> (groupNameA+groupNameB+groupNameC+etc…)
                    const set = new Set();
                    dataPart.forEach((p) => set.add(p.name.split(':')[1]));
                    const groupNames =
                        Array.from(set.keys()).sort().slice(0, 3).join('+') +
                        (set.size > 3 ? '+etc…' : '');
                    groupedName += ` (${groupNames})`;
                }
                const aggregate = dataPart.reduce(
                    (reduced, point) => reduced + point.after - point.before,
                    0
                );
                return { name: groupedName, aggregate };
            })
            .sort((a, b) => b.aggregate - a.aggregate);

        // Sum all time in this particular group for percentage
        const totalAggregateTime = points.reduce(
            (reduced, { aggregate }) => reduced + aggregate,
            0
        );

        // Textify
        const tabledText = points
            .map(({ name, aggregate }) => {
                const percent = totalAggregateTime
                    ? (aggregate / totalAggregateTime) * 100
                    : 0;
                // 7 for the time string, 4 for percent string, 3 to compensate for column char of the table
                const maxBarSize =
                    (process.stdout.columns || 80) -
                    this.nameMaxLen -
                    7 -
                    4 -
                    6;
                return [
                    // maximum of 20
                    padRight(
                        new Array(indentation + 1).join('  ') +
                            name.slice(0, this.nameMaxLen),
                        this.nameMaxLen
                    ),
                    // max of 7 characters
                    padLeft(prettyMs(aggregate).slice(0, 7), 7),
                    getBarText(percent, maxBarSize),
                    // maximum of 4 character (number + '%')
                    padLeft(`${Math.round(percent)}%`, 4),
                ].join('  ');
            })
            .join('\n');

        // Print the table!
        console.log(tabledText);
    }

    print(data) {
        console.log(
            chalk.bgWhite.black(
                padRight(
                    ' Sorted by grouping (aggregate of all thread)',
                    process.stdout.columns || 80
                )
            )
        );
        this._print(data, [1]);

        console.log(
            chalk.bgWhite.black(
                padRight(' Sorted by subgroup', process.stdout.columns || 80)
            )
        );
        this._print(data, [1, 2]);

        console.log(
            chalk.bgWhite.black(
                padRight(' Sorted by pid', process.stdout.columns || 80)
            )
        );
        this._print(data, [0]);

        console.log(
            new Array((process.stdout.columns || 80) + 1).join(figure.line)
        );
        console.log(
            chalk.white(
                `Process finished in ${chalk.bold(
                    prettyMs(Date.now() - this.processStart)
                )}.`
            )
        );
    }
}

module.exports = CliPrinter;

const tap = require('tap');
const CliPrinter = require('../src/helpers/analytics/cli-printer');

function captureConsoleLog(fn) {
    const lines = [];
    const original = console.log;
    console.log = (...args) => lines.push(args.join(' '));
    try {
        fn();
    } finally {
        console.log = original;
    }
    return lines.join('\n');
}

tap.test(
    'renders bar/separator glyphs instead of undefined interop artifacts',
    (t) => {
        const printer = new CliPrinter({ enableColor: false });
        const data = [
            { name: '1:groupA:sub', before: 0, after: 300 },
            { name: '1:groupB:sub', before: 0, after: 700 },
        ];

        const output = captureConsoleLog(() => printer.print(data));

        t.match(output, /█/, 'bar chart renders the square glyph');
        t.match(output, /─/, 'footer renders the line glyph');
        t.notMatch(
            output,
            /undefined/,
            'no undefined interop artifacts leak into output'
        );
        t.end();
    }
);

tap.test('renders a report when every measurement took zero time', (t) => {
    const printer = new CliPrinter({ enableColor: false });
    const data = [
        { name: '1:groupA:sub', before: 5, after: 5 },
        { name: '1:groupB:sub', before: 7, after: 7 },
    ];

    let output = '';
    t.doesNotThrow(() => {
        output = captureConsoleLog(() => printer.print(data));
    }, 'a zero total duration does not throw');
    t.match(output, /0%/, 'percentages fall back to 0%');
    t.notMatch(output, /NaN/, 'no NaN leaks into the report');
    t.end();
});

tap.test('a failing printer cannot fail the process on exit', (t) => {
    const collector = require('../src/helpers/analytics/analytics-collector');
    const originalOptions = collector.options;
    const originalError = console.error;
    const errors = [];

    collector.data.push({
        name: '1:groupA:sub',
        pid: 1,
        before: 0,
        after: 1,
    });
    collector.setOptions({
        printer: {
            print() {
                throw new Error('printer exploded');
            },
        },
    });
    console.error = (...args) => errors.push(args);

    try {
        t.doesNotThrow(
            () => collector.onExit(),
            'a throwing printer does not propagate out of the exit handler'
        );
        t.equal(errors.length, 1, 'the failure is reported, not silenced');
        t.match(
            errors[0],
            [/Analytics printer error/, Error],
            'the original error is surfaced for debugging'
        );
    } finally {
        console.error = originalError;
        collector.data.length = 0;
        collector.setOptions(originalOptions);
    }

    t.end();
});

tap.test('handles narrow terminal widths without throwing RangeError', (t) => {
    const printer = new CliPrinter({ enableColor: false });
    const data = [
        { name: '1:groupA:sub', before: 0, after: 300 },
        { name: '1:groupB:sub', before: 0, after: 700 },
    ];

    const originalColumns = process.stdout.columns;

    t.test('narrow terminal (30 columns)', (t) => {
        Object.defineProperty(process.stdout, 'columns', {
            value: 30,
            configurable: true,
        });

        try {
            let errorThrown = false;
            let output = '';

            try {
                output = captureConsoleLog(() => printer.print(data));
            } catch (err) {
                errorThrown = true;
                t.fail(`Should not throw, but got: ${err.message}`);
            }

            t.notOk(errorThrown, 'does not throw RangeError');
            t.ok(output.length > 0, 'produces output');
            t.notMatch(
                output,
                /undefined/,
                'output does not contain undefined'
            );
        } finally {
            Object.defineProperty(process.stdout, 'columns', {
                value: originalColumns,
                configurable: true,
            });
        }

        t.end();
    });

    t.test('moderate narrow terminal (40 columns)', (t) => {
        Object.defineProperty(process.stdout, 'columns', {
            value: 40,
            configurable: true,
        });

        try {
            let errorThrown = false;
            let output = '';

            try {
                output = captureConsoleLog(() => printer.print(data));
