class Entry {
    static getTypeForConfig(typeConfigs, id) {
        if (isNodeModule(id)) return 'node_modules';
        const type = typeConfigs.find((type) => type.test(id));
        return type ? type.name : '_others';
    }

    constructor(id) {
        this.id = id;

        // property is filled by cache where they have more context
        this.normalizedId;
        this.variation;
        this.runtime; // one of 'browser', 'main', 'package', 'isomorphic'
        this.type; // one of the ids of types defined in mendelrc.

        this.istSource;
        this.istDeps;
        this.istMap;
        this.rawSource;
        this.rawDeps;
        this.source;
        // Transform used for source
        this.transformIds;
        this.map;
        // dependencies
        this.deps;
        this.dependents;

        // Other metadata
        this.error; // If there is an error
        this.done; // Whether entry went through upto GST step in pipeline

        this.reset();
    }

    // Let's store rawSource
    setSource(source, deps, map) {
        this.source = source;
        this.deps = deps;

        if (map) {
            this.map = map;
        }

        if (!this.rawSource) {
            this.rawSource = source;
            this.rawDeps = deps;
        }
    }

    hasSource() {
        return !!this.source;
    }

    getDependency() {
        return this.deps;
    }

    reset() {
        this.rawSource = null;
        this.rawDeps = {};
        this.source = null;
        this.map = null;
        this.deps = {};
        this.dependents = [];
        this.error = null;
        this.done = false;
    }

    // For debugging purposes
    debug() {
        return {
            id: this.id,
            normalizedId: this.normalizedId,
            variation: this.variation,
            dependents: this.dependents,
            source: this.source,
            deps: this.deps,
            map: this.map,
        };
    }
}

function isNodeModule(id) {
    return id.indexOf('node_modules') >= 0;
}

module.exports = Entry;

const BaseStep = require('../step');
const path = require('path');
const fs = require('fs');
const analytics = require('../../helpers/analytics/analytics')('fs');
const debugError = require('debug')('mendel:reader:error');

class FileReader extends BaseStep {
    constructor({ registry, depsResolver }, { projectRoot, types }) {
        super();
        this.depsResolver = depsResolver;
        this.projectRoot = projectRoot;
        this.registry = registry;
        this._types = types;
        this.sourceExt = new Set();
    }

    perform(entry) {
        // raw can exist without read step in case of virtual files and others.
        if (entry.rawSource) return this.emit('done', { entryId: entry.id });
        const filePath = path.resolve(this.projectRoot, entry.id);
        const { type } = entry;
        const { isBinary } = this._types.get(type) || { isBinary: true };

        analytics.tic('read');
        fs.readFile(filePath, isBinary ? 'binary' : 'utf8', (error, source) => {
            analytics.toc('read');
            if (error) {
                console.error(
                    [
                        `[Mendel] Critical error while reading "${filePath}".`,
                    ].join(' ')
                );
                debugError(`Error message for ${filePath}: ${error.stack}`);
                this.emit('error', { id: entry.id, error });
                return;
            }

            this.registry.addSource({ id: entry.id, source, deps: {} });
            this.emit('done', { entryId: entry.id });
        });
    }
}

module.exports = FileReader;

